-- Enforce technician job ticket access control
CREATE POLICY technician_access_ticket ON service_tickets
FOR UPDATE
USING (
  auth.uid() = technician_id 
  OR auth.jwt() ->> 'role' IN ('admin', 'dispatcher')
)
WITH CHECK (
  status IN ('in_progress', 'completed', 'pending_parts')
);

export const VALID_TRANSITIONS: Record<TicketStatus, TicketStatus[]> = {
  created: ['dispatched', 'cancelled'],
  dispatched: ['en_route', 'cancelled'],
  en_route: ['in_progress', 'delayed'],
  in_progress: ['completed', 'pending_parts'],
  pending_parts: ['in_progress', 'cancelled'],
  completed: [],
  cancelled: []
};

export function validateTransition(current: TicketStatus, next: TicketStatus): boolean {
  return VALID_TRANSITIONS[current]?.includes(next) ?? false;
}

app.get('/healthz', async (req, res) => {
  try {
    const dbCheck = await firestore.collection('_health').limit(1).get();
    res.status(200).json({
      status: 'healthy',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      memory: process.memoryUsage().rss
    });
  } catch (err) {
    res.status(503).json({ status: 'unhealthy', error: err.message });
  }
});

export type BaristaIntent = 
  | 'recommend' | 'cheapest' | 'budget' | 'ingredient' 
  | 'customize' | 'details' | 'pairing' | 'compare';

export async function parseBaristaIntent(prompt: string): Promise<IntentResult> {
  const response = await gemini.generateContent({
    contents: [{ role: 'user', parts: [{ text: PROMPT_TEMPLATE(prompt) }] }],
    generationConfig: { responseMimeType: 'application/json' }
  });
  return JSON.parse(response.text);
}

function calculateEMI(principal, annualRate, tenureMonths) {
  const monthlyRate = annualRate / (12 * 100);
  const emi = (principal * monthlyRate * Math.pow(1 + monthlyRate, tenureMonths)) / 
              (Math.pow(1 + monthlyRate, tenureMonths) - 1);
  return Number(emi.toFixed(2));
}
